INSERT INTO membership_users (source_id, group_id, user_id, occurred_at, update_id, payload, present, generation, tag, tag_generation) VALUES (?1,?2,?3,?4,?5,?6,?7,?8,?9,?8) ON CONFLICT(source_id,group_id,user_id) DO UPDATE SET occurred_at=excluded.occurred_at, update_id=excluded.update_id, payload=excluded.payload, present=excluded.present, generation=excluded.generation, tag=CASE WHEN ?10 THEN excluded.tag ELSE membership_users.tag END, tag_generation=CASE WHEN ?10 THEN excluded.tag_generation ELSE membership_users.tag_generation END;
